import org.springframework.data.repository.query.Param;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    /** The sheet's claims in list order: newest listed first. */
    List<Claim> findBySheetIdOrderByListedDescIdDesc(String sheetId);

    /** Gives the claim the next place in the list, so it is listed first under its person. */
    @Modifying(flushAutomatically = true)
    @Query(value = "UPDATE claim SET listed = NEXT VALUE FOR claim_listing WHERE id = :id", nativeQuery = true)
    void relist(@Param("id") Long id);

    List<Claim> findBySheetIdAndPersonIdOrderByIdDesc(String sheetId, Long personId);

    boolean existsBySheetIdAndPersonIdAndNumberAndStatus(String sheetId, Long personId, String number,
            ClaimStatus status);

    Optional<Claim> findBySheetIdAndNumber(String sheetId, String number);

    /**
     * The last place given in the sheet's number sequence, by a claim holding it or one that gave it up when
     * re-dated; null when none has been.
     */
    @Query(value = "SELECT MAX(n) FROM (SELECT number_in_sequence AS n FROM claim WHERE sheet_id = :sheetId"
            + " AND number_sequence = :sequence UNION ALL SELECT number_in_sequence FROM claim_number_retired"
            + " WHERE sheet_id = :sheetId AND number_sequence = :sequence) AS given", nativeQuery = true)
    Long lastInSequence(@Param("sheetId") String sheetId, @Param("sequence") String sequence);

    /** Records a period number a claim gave up, so it is never given again. */
    @Modifying(flushAutomatically = true)
    @Query(value = "INSERT INTO claim_number_retired (sheet_id, number_sequence, number_in_sequence)"
            + " VALUES (:sheetId, :sequence, :place)", nativeQuery = true)
    void retireNumber(@Param("sheetId") String sheetId, @Param("sequence") String sequence,
            @Param("place") Long place);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);

    /** The claim, locked until the transaction ends, so two status changes to it never interleave. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    Optional<Claim> findWithLockByIdAndSheetId(Long id, String sheetId);

    /** The sheet's claims an editor holds. */
    List<Claim> findBySheetIdAndLockedByNotNull(String sheetId);
}
package net.officefloor.hq.app.paste;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** Adds a draft claim for each pasted line of name,amount,date,note, all of them or none. */
@Service
public class PasteService {

    /** A pasted line read into the claim form's fields, for a person on the sheet. */
    private record Line(Person person, BigDecimal amount, LocalDate date, String note) {
    }

    private final PersonRepository people;
    private final ClaimService claims;

    public PasteService(PersonRepository people, ClaimService claims) {
        this.people = people;
        this.claims = claims;
    }

    /**
     * Reads every line first by the claim form's rules, then adds a claim per line in order, each by the rules of
     * adding one claim. One change: any line refused refuses them all, and nothing is stored or audited.
     */
    @Transactional
    public List<Claim> paste(String by, String sheetId, String text) {
        List<Line> lines = new ArrayList<>();
        int n = 0;
        for (String raw : text.split("\\r?\\n")) {
            n++;
            if (raw.isBlank()) {
                continue;
            }
            lines.add(read(sheetId, n, raw));
        }
        if (lines.isEmpty()) {
            throw refused("Paste at least one line of name,amount,date,note.");
        }
        List<Claim> added = new ArrayList<>();
        for (Line l : lines) {
            added.add(claims.add(by, sheetId, l.person().getId(), l.amount(), l.date(), l.note(), null));
        }
        return added;
    }

    private Line read(String sheetId, int n, String raw) {
        String[] f = raw.split(",", 4);
        if (f.length < 2) {
            throw refused("Line " + n + " needs at least a name and an amount.");
        }
        String name = f[0].strip();
        Person person = name.isEmpty() ? null
                : people.findBySheetIdAndNameIgnoreCase(sheetId, name).orElse(null);
        if (person == null) {
            throw refused("Line " + n + " names no one on the sheet.");
        }
        BigDecimal amount;
        try {
            amount = new BigDecimal(f[1].strip());
        } catch (NumberFormatException e) {
            throw refused("Line " + n + " has no amount.");
        }
        // the claim form's amount: up to twelve whole digits and two decimals
        if (amount.scale() > 2 || amount.precision() - amount.scale() > 12) {
            throw refused("Line " + n + " has an amount with more than two decimals.");
        }
        LocalDate date = null;
        String dateText = f.length > 2 ? f[2].strip() : "";
        if (!dateText.isEmpty()) {
            try {
                date = LocalDate.parse(dateText);
            } catch (DateTimeParseException e) {
                throw refused("Line " + n + " has a date that is not yyyy-mm-dd.");
            }
        }
        String note = f.length > 3 ? f[3] : "";
        if (note.length() > 500) {
            throw refused("Line " + n + " has a note longer than 500 characters.");
        }
        return new Line(person, amount, date, note);
    }

    private static ResponseStatusException refused(String reason) {
        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, reason);
    }
}
package db.migration;

import java.sql.Connection;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.holiday.HolidayService;
import org.flywaydb.core.api.migration.BaseJavaMigration;
import org.flywaydb.core.api.migration.Context;

/**
 * Terms count business days: every claim's due-by becomes the terms-th business day after its date, skipping
 * weekends and the sheet's holidays as they are now. The terms each claim was fixed with are read back from its
 * due-by: its calendar days after the claim's date, less the run of holidays just before it that it was moved past.
 */
public class V53__claim_due_by_business_days extends BaseJavaMigration {

    @Override
    public void migrate(Context context) throws Exception {
        Connection db = context.getConnection();
        Map<String, Set<LocalDate>> holidays = new HashMap<>();
        try (Statement select = db.createStatement();
                ResultSet rs = select.executeQuery("SELECT sheet_id, on_date FROM holiday")) {
            while (rs.next()) {
                holidays.computeIfAbsent(rs.getString(1), k -> new HashSet<>()).add(rs.getDate(2).toLocalDate());
            }
        }
        try (Statement select = db.createStatement();
                ResultSet rs = select.executeQuery("SELECT id, sheet_id, claim_date, due_by FROM claim");
                PreparedStatement update = db.prepareStatement("UPDATE claim SET due_by = ? WHERE id = ?")) {
            while (rs.next()) {
                Set<LocalDate> days = holidays.getOrDefault(rs.getString(2), Set.of());
                LocalDate date = rs.getDate(3).toLocalDate();
                LocalDate fixed = rs.getDate(4).toLocalDate();
                while (fixed.minusDays(1).compareTo(date) >= 0 && days.contains(fixed.minusDays(1))) {
                    fixed = fixed.minusDays(1);
                }
                int terms = (int) Math.max(0, ChronoUnit.DAYS.between(date, fixed));
                update.setDate(1, Date.valueOf(HolidayService.businessDaysAfter(date, terms, days)));
                update.setLong(2, rs.getLong(1));
                update.addBatch();
            }
            update.executeBatch();
        }
    }
}
